"""Extract only the consumed input schemas from a pinned platform checkout.

No network or platform runtime is required. Runtime validators and deployment
acceptance remain the producer's responsibility; OpenAPI describes shape only.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import subprocess
from pathlib import Path


ROOT = Path(__file__).parents[1] / "platform"
INPUTS = (
    "ApplicationEnvelopeV1Alpha2", "PolicyCreate", "GroupCreate",
    "ServiceRequest", "Approval", "Governance", "Rotation",
)


def encode(value: dict) -> bytes:
    return (json.dumps(value, indent=2, sort_keys=True) + "\n").encode()


def source_bytes(path: Path) -> bytes:
    """Normalize text checkout line endings so Git autocrlf does not alter pins."""
    return path.read_text(encoding="utf-8").encode("utf-8")


def snapshot(checkout: Path, baseline: dict) -> bytes:
    revision = subprocess.check_output(
        ["git", "-C", str(checkout), "rev-parse", "HEAD"], text=True
    ).strip()
    if revision != baseline["revision"]:
        raise ValueError("Checkout does not match the reviewed platform revision")
    for name, expected in baseline["sourceSha256"].items():
        if hashlib.sha256(source_bytes(checkout / name)).hexdigest() != expected:
            raise ValueError(f"Reviewed platform source changed: {name}")
    schemas = json.loads(source_bytes(checkout / "docs/api/openapi.json"))["components"]["schemas"]
    definitions = {}

    def visit(value):
        if isinstance(value, dict):
            reference = value.get("$ref", "")
            if reference.startswith("#/components/schemas/"):
                name = reference.removeprefix("#/components/schemas/")
                if name not in definitions:
                    definitions[name] = None
                    definitions[name] = visit(schemas[name])
                return {**value, "$ref": "#/$defs/" + name}
            return {key: visit(item) for key, item in value.items()}
        if isinstance(value, list):
            return [visit(item) for item in value]
        return value

    for name in INPUTS:
        definitions[name] = visit(schemas[name])
    return encode({
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "description": "Generated by tools.build_platform_snapshot from the revision in baseline.json. Shape validation only.",
        "$defs": definitions,
    })


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkout", type=Path)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    baseline = json.loads((ROOT / "baseline.json").read_bytes())
    payload = snapshot(args.checkout, baseline)
    target = ROOT / "upstream-inputs.schema.json"
    if args.check:
        if target.read_bytes() != payload:
            raise SystemExit("Platform input schema snapshot has drifted")
        print("Pinned platform source and input schema snapshot match")
    else:
        target.write_bytes(payload)


if __name__ == "__main__":
    main()
